<INITIAL>"to" {return TO;}
<INITIAL>"if" {return IF;}
<INITIAL>"else" {return ELSE;}
<INITIAL>"elseif" {return ELSEIF;}
<INITIAL>"function"|"func" {return FUNCTION;}
<INITIAL>"for" {return FOR;}
<INITIAL>"in" {return IN;}
<INITIAL>"spawn" {return SPAWN;}
