#!/usr/bin/env python3
"""
Controlled MCP Test Server for Pifari Agent Runtime & MCP Gateway.
Supports JSON-RPC 2.0 over:
  - stdio (default)
  - HTTP (--http <port>) with Mcp-Session-Id header and JSON/SSE response modes.
All operations are deterministic, local, and reversible.
"""

import json
import sys
import time
from http.server import BaseHTTPRequestHandler, HTTPServer

PROTOCOL_VERSION = "2025-03-26"

TOOLS = [
    {
        "name": "collect_dataset",
        "description": "Coleta serie numerica deterministica de telemetria cientifica",
        "annotations": {"readOnlyHint": True, "sideEffect": False},
        "inputSchema": {
            "type": "object",
            "properties": {"source": {"type": "string"}},
            "required": ["source"],
        },
    },
    {
        "name": "analyze_series",
        "description": "Analisa metricas estatisticas e anomalias de serie coletada",
        "annotations": {"readOnlyHint": True, "sideEffect": False},
        "inputSchema": {
            "type": "object",
            "properties": {"dataset": {"type": "string"}},
            "required": ["dataset"],
        },
    },
    {
        "name": "build_report",
        "description": "Sintetiza relatorio executivo consolidado a partir do contexto",
        "annotations": {"readOnlyHint": True, "sideEffect": False},
        "inputSchema": {
            "type": "object",
            "properties": {
                "collector_summary": {"type": "string"},
                "analysis_summary": {"type": "string"},
            },
        },
    },
    {
        "name": "write_audit_entry",
        "description": "Registra entrada mutavel de auditoria (nao idempotente)",
        "annotations": {"readOnlyHint": False, "sideEffect": True},
        "inputSchema": {
            "type": "object",
            "properties": {"entry": {"type": "string"}},
            "required": ["entry"],
        },
    },
    {
        "name": "slow_op",
        "description": "Operacao lenta controlada para testar timeout e cancelamento",
        "annotations": {"readOnlyHint": True, "sideEffect": False},
        "inputSchema": {
            "type": "object",
            "properties": {"delay_ms": {"type": "integer"}},
        },
    },
    {
        "name": "restricted_op",
        "description": "Operacao sensivel bloqueada por padrao pelo Policy Engine",
        "annotations": {"readOnlyHint": False, "sideEffect": True},
        "inputSchema": {"type": "object"},
    },
]

RESOURCES = [
    {
        "uri": "resource://pifari/runtime_spec",
        "name": "Pifari Runtime Spec",
        "mimeType": "application/json",
    },
    {
        "uri": "resource://pifari/dataset_catalog",
        "name": "Catalogo de Datasets de Teste",
        "mimeType": "text/plain",
    },
]


def handle_rpc_Object(msg: dict):
    method = msg.get("method", "")
    req_id = msg.get("id", None)
    params = msg.get("params") or {}

    # Notifications do not return a JSON-RPC response
    if req_id is None or method.startswith("notifications/"):
        return None

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {
                    "tools": {"listChanged": False},
                    "resources": {"subscribe": False, "listChanged": False},
                    "prompts": {"listChanged": False},
                },
                "serverInfo": {
                    "name": "pifari-mock-mcp-server",
                    "version": "1.0.0",
                },
            },
        }

    if method == "tools/list":
        return {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {"tools": TOOLS},
        }

    if method == "resources/list":
        return {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {"resources": RESOURCES},
        }

    if method == "resources/read":
        uri = params.get("uri", "")
        if uri == "resource://pifari/runtime_spec":
            text = (
                '{"engine":"Pifari-Agent-Runtime","version":"3.1","mcp":"2025-03-26"}'
            )
        elif uri == "resource://pifari/dataset_catalog":
            text = "datasets: [sensor_alpha, quantum_flux, mlp_weights]"
        else:
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "error": {"code": -32602, "message": f"Resource not found: {uri}"},
            }
        return {
            "jsonrpc": "2.0",
            "id": req_id,
            "result": {
                "contents": [{"uri": uri, "mimeType": "text/plain", "text": text}]
            },
        }

    if method == "tools/call":
        name = params.get("name", "")
        args = params.get("arguments") or {}

        if name == "collect_dataset":
            src = args.get("source", "default")
            text = f"dataset={src};samples=4;values=[12.5,18.0,24.5,31.0];checksum=OK"
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [{"type": "text", "text": text}],
                    "isError": False,
                },
            }

        if name == "analyze_series":
            ds = args.get("dataset", "unknown")
            text = f"analysis_for=({ds});mean=21.50;max=31.00;anomaly=false;confidence=0.99"
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [{"type": "text", "text": text}],
                    "isError": False,
                },
            }

        if name == "build_report":
            c_sum = args.get("collector_summary", "")
            a_sum = args.get("analysis_summary", "")
            text = f"RELATORIO_CONSOLIDADO | Coleta=[{c_sum}] | Analise=[{a_sum}] | Status=VERIFICADO"
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [{"type": "text", "text": text}],
                    "isError": False,
                },
            }

        if name == "write_audit_entry":
            entry = args.get("entry", "noop")
            text = f"AUDIT_COMMITTED:{entry}"
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [{"type": "text", "text": text}],
                    "isError": False,
                },
            }

        if name == "slow_op":
            delay_ms = int(args.get("delay_ms", 400))
            time.sleep(delay_ms / 1000.0)
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [
                        {"type": "text", "text": f"completed_after_{delay_ms}ms"}
                    ],
                    "isError": False,
                },
            }

        if name == "restricted_op":
            return {
                "jsonrpc": "2.0",
                "id": req_id,
                "result": {
                    "content": [{"type": "text", "text": "RESTRICTED_EXECUTED"}],
                    "isError": False,
                },
            }

        return {
            "jsonrpc": "2.0",
            "id": req_id,
            "error": {"code": -32601, "message": f"Unknown tool: {name}"},
        }

    return {
        "jsonrpc": "2.0",
        "id": req_id,
        "error": {"code": -32601, "message": f"Method not found: {method}"},
    }


def run_stdio():
    try:
        for raw_line in sys.stdin:
            line = raw_line.strip()
            if not line:
                continue
            try:
                msg = json.loads(line)
            except Exception as exc:
                err = {
                    "jsonrpc": "2.0",
                    "id": None,
                    "error": {"code": -32700, "message": f"Parse error: {exc}"},
                }
                sys.stdout.write(json.dumps(err, separators=(",", ":")) + "\n")
                sys.stdout.flush()
                continue

            resp = handle_rpc_Object(msg)
            if resp is not None:
                sys.stdout.write(json.dumps(resp, separators=(",", ":")) + "\n")
                sys.stdout.flush()
    except (BrokenPipeError, IOError):
        try:
            sys.stdout.close()
        except Exception:
            pass


class McpHttpHandler(BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        pass

    def do_POST(self):
        length = int(self.headers.get("Content-Length", "0"))
        body = self.rfile.read(length).decode("utf-8", errors="replace")
        try:
            msg = json.loads(body)
        except Exception:
            self.send_response(400)
            self.end_headers()
            return

        resp = handle_rpc_Object(msg)
        if resp is None:
            self.send_response(202)
            self.send_header("Mcp-Session-Id", "pifari-http-session-01")
            self.send_header("Content-Length", "2")
            self.end_headers()
            self.wfile.write(b"{}")
            return

        payload = json.dumps(resp, separators=(",", ":")).encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Mcp-Session-Id", "pifari-http-session-01")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)


def run_http(port: int):
    server = HTTPServer(("127.0.0.1", port), McpHttpHandler)
    server.serve_forever()


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "--http":
        run_http(int(sys.argv[2]))
    else:
        run_stdio()

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "agent_runtime.h"
#include "mcp_gateway.h"
#include "mcp_server.h"

static char *dummy_tool_cb(const char *fn_name, size_t argc, const char **argv, int *out_is_error) {
    if (out_is_error)
        *out_is_error = 0;
    char *buf = malloc(128);
    snprintf(buf, 128, "%s:%zu:%s", fn_name, argc, (argc > 0 && argv[0]) ? argv[0] : "");
    return buf;
}

int main(void) {
    agent_runtime_reset();

    /* 1. Register controlled stdio MCP test server */
    McpStatus st = mcp_gateway_register_server("mcp_test", MCP_TRANSPORT_STDIO,
                                               "python3 tests/mock_mcp_server.py", "", 2000, 4);
    assert(st == MCP_STATUS_OK);

    /* 2. Connect & negotiate MCP protocol + discover tools & resources */
    size_t tool_count = 0;
    st = mcp_gateway_discover_tools("mcp_test", &tool_count);
    assert(st == MCP_STATUS_OK);
    assert(tool_count == 6);

    size_t res_count = 0;
    st = mcp_gateway_discover_resources("mcp_test", &res_count);
    assert(st == MCP_STATUS_OK);
    assert(res_count == 2);

    const McpServerEntry *srv = mcp_gateway_get_server("mcp_test");
    assert(srv != NULL);
    assert(srv->connected == 1);
    assert(strcmp(srv->negotiated_version, MCP_PROTOCOL_VERSION) == 0);
    assert(srv->capabilities_tools == 1);
    assert(srv->capabilities_resources == 1);

    McpCallResult rres =
        mcp_gateway_read_resource("mcp_test", "resource://pifari/runtime_spec", 1000);
    assert(rres.status == MCP_STATUS_OK);
    assert(strstr(rres.output_text, "Pifari-Agent-Runtime") != NULL);

    /* 3. Register 3 agents with distinct roles */
    assert(agent_runtime_register_agent("ag_collector", "Data Collector", "Coletar series",
                                        "local-deterministic", 2, 1500) == 0);
    assert(agent_runtime_register_agent("ag_analyst", "Statistical Analyst", "Analisar series",
                                        "local-deterministic", 2, 1500) == 0);
    assert(agent_runtime_register_agent("ag_reporter", "Executive Reporter", "Gerar relatorio",
                                        "local-deterministic", 1, 1500) == 0);

    const ArAgentEntry *ag1 = agent_runtime_get_agent("ag_collector");
    assert(ag1 != NULL && ag1->version == 1);

    /* 4. Policy Engine: default-deny blocks unauthorized tools and side effects */
    McpCallResult denied =
        agent_runtime_invoke_mcp("ag_collector", "mcp_test", "restricted_op", "{}", 1000);
    assert(denied.status == MCP_STATUS_ERR_POLICY_DENIED);

    /* Authorize read-only tools for the 3 agents */
    assert(agent_runtime_policy_allow("ag_collector", "mcp_test", "collect_dataset", 0) == 0);
    assert(agent_runtime_policy_allow("ag_collector", "mcp_test", "slow_op", 0) == 0);
    assert(agent_runtime_policy_allow("ag_analyst", "mcp_test", "analyze_series", 0) == 0);
    assert(agent_runtime_policy_allow("ag_reporter", "mcp_test", "build_report", 0) == 0);

    /* Side-effect tool without allow_side_effects=1 must still be denied */
    assert(agent_runtime_policy_allow("ag_reporter", "mcp_test", "write_audit_entry", 0) == 0);
    McpCallResult se_denied = agent_runtime_invoke_mcp(
        "ag_reporter", "mcp_test", "write_audit_entry", "{\"entry\":\"test1\"}", 1000);
    assert(se_denied.status == MCP_STATUS_ERR_POLICY_DENIED);

    /* Grant side-effect permission and verify duplicate side-effect protection */
    assert(agent_runtime_policy_allow("ag_reporter", "mcp_test", "write_audit_entry", 1) == 0);
    McpCallResult se_ok = agent_runtime_invoke_mcp("ag_reporter", "mcp_test", "write_audit_entry",
                                                   "{\"entry\":\"commit_01\"}", 1000);
    assert(se_ok.status == MCP_STATUS_OK);
    assert(strstr(se_ok.output_text, "AUDIT_COMMITTED:commit_01") != NULL);

    McpCallResult se_dup = agent_runtime_invoke_mcp("ag_reporter", "mcp_test", "write_audit_entry",
                                                    "{\"entry\":\"commit_01\"}", 1000);
    assert(se_dup.status == MCP_STATUS_ERR_DUPLICATE_CALL);

    /* 5. Context Store versioning and no-op invariance */
    int v1 = agent_runtime_ctx_put("config.mode", "production_test", "ag_collector", "init");
    assert(v1 == 1);
    int v_noop = agent_runtime_ctx_put("config.mode", "production_test", "ag_collector", "init");
    assert(v_noop == 1);
    int v2 = agent_runtime_ctx_put("config.mode", "verified_mode", "ag_collector", "init");
    assert(v2 == 2);
    assert(strcmp(agent_runtime_ctx_get("config.mode"), "verified_mode") == 0);

    /* 6. Task Engine & Parallel DAG Execution with Dependencies and Cancellation */
    assert(agent_runtime_create_task("task_collect", "ag_collector", "mcp_test", "collect_dataset",
                                     "{\"source\":\"sensor_alpha\"}", "ctx.raw_dataset", 10,
                                     1500) == 0);

    assert(agent_runtime_create_task("task_analyze", "ag_analyst", "mcp_test", "analyze_series",
                                     "{\"dataset\":\"sensor_alpha_baseline\"}", "ctx.analysis", 10,
                                     1500) == 0);

    /* Dependent task waiting on both task_collect and task_analyze */
    assert(agent_runtime_create_task("task_report", "ag_reporter", "mcp_test", "build_report",
                                     "{\"collector_summary\":\"{{ctx:ctx.raw_dataset}}\","
                                     "\"analysis_summary\":\"{{ctx:ctx.analysis}}\"}",
                                     "ctx.final_report", 5, 1500) == 0);
    assert(agent_runtime_task_add_dep("task_report", "task_collect") == 0);
    assert(agent_runtime_task_add_dep("task_report", "task_analyze") == 0);

    /* Task that exceeds deadline and gets cancelled by timeout */
    assert(agent_runtime_create_task("task_slow_timeout", "ag_collector", "mcp_test", "slow_op",
                                     "{\"delay_ms\":350}", "", 1, 70) == 0);

    /* Task explicitly cancelled before execution */
    assert(agent_runtime_create_task("task_explicit_cancel", "ag_collector", "mcp_test",
                                     "collect_dataset", "{\"source\":\"aborted\"}", "", 1,
                                     1000) == 0);
    assert(agent_runtime_task_cancel("task_explicit_cancel", "cancelado_pelo_coordenador") == 0);

    int completed = agent_runtime_dag_run(2);
    assert(completed == 3);

    const ArTaskEntry *tc = agent_runtime_get_task("task_collect");
    const ArTaskEntry *ta = agent_runtime_get_task("task_analyze");
    const ArTaskEntry *tr = agent_runtime_get_task("task_report");
    const ArTaskEntry *ts = agent_runtime_get_task("task_slow_timeout");
    const ArTaskEntry *tx = agent_runtime_get_task("task_explicit_cancel");

    assert(tc && tc->state == TASK_STATE_COMPLETED);
    assert(ta && ta->state == TASK_STATE_COMPLETED);
    assert(tr && tr->state == TASK_STATE_COMPLETED);
    assert(ts && ts->state == TASK_STATE_CANCELLED);
    assert(tx && tx->state == TASK_STATE_CANCELLED);
    assert(strstr(tr->result_text, "RELATORIO_CONSOLIDADO") != NULL);
    assert(strstr(tr->result_text, "sensor_alpha") != NULL);

    /* 7. Artifact Manager & Telemetry Engine */
    assert(agent_runtime_artifact_save("art_unit_report", "/tmp/pifari_test_artifact.txt",
                                       tr->result_text, "ag_reporter", "task_report") == 0);

    const ArArtifactEntry *art = agent_runtime_get_artifact("art_unit_report");
    assert(art != NULL);
    assert(art->byte_size == strlen(tr->result_text));
    assert(strlen(art->checksum_fnv1a) == 16);

    assert(agent_runtime_progress_percent() == 100);
    assert(agent_runtime_telemetry_count() >= 10);
    assert(agent_runtime_export_report_json("/tmp/pifari_test_telemetry.json") == 0);

    unlink("/tmp/pifari_test_artifact.txt");
    unlink("/tmp/pifari_test_telemetry.json");
    agent_runtime_reset();

    /* 8. Native MCP Server Engine C unit verification */
    pifari_mcp_server_init("unit-srv", "1.0.0");
    const char *params[1] = {"x"};
    assert(pifari_mcp_server_register_tool("dobro", "Dobra valor", "fn_dobro", 1, params, 1) == 0);
    assert(pifari_mcp_server_register_resource("resource://unit/info", "info", "application/json",
                                               "{\"ok\":true}") == 0);
    char rpc_out[2048];
    assert(pifari_mcp_server_handle_line(
               "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{}}",
               dummy_tool_cb, rpc_out, sizeof(rpc_out)) == 1);
    assert(strstr(rpc_out, "2025-03-26") != NULL);
    assert(pifari_mcp_server_handle_line(
               "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/"
               "call\",\"params\":{\"name\":\"dobro\",\"arguments\":{\"x\":\"42\"}}}",
               dummy_tool_cb, rpc_out, sizeof(rpc_out)) == 1);
    assert(strstr(rpc_out, "fn_dobro:1:42") != NULL);

    printf("test_agent_runtime: ok\n");
    return 0;
}

#include "../backend/optimization/ast_ir.h"
#include "../backend/numeric_buffer.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

int main(void) {
    Node *x = node_new("Name", "x", 1, 1);
    Node *two = node_new("Integer", "2", 1, 5);
    Node *mul = node_pair("Binary", "*", x, two, 1, 3);
    Node *one = node_new("Integer", "1", 1, 9);
    Node *expr = node_pair("Binary", "+", mul, one, 1, 7);
    PifariExprGraph graph;
    char error[160];
    assert(pifari_ast_expr_to_ir(expr, "x", &graph, error, sizeof(error)) == 0);
    double result = 0.0;
    assert(pifari_graph_eval(&graph, 4.0, &result) == 0);
    assert(result == 9.0);
    assert(pifari_graph_workspace_slots(&graph) < graph.count);
    assert(pifari_graph_map(&graph, (double[]){1, 2, 3}, (double[3]){0}, 0) == 0);
    pifari_graph_destroy(&graph);
    node_free(expr);

    Node *unknown = node_new("Name", "other", 1, 1);
    assert(pifari_ast_expr_to_ir(unknown, "x", &graph, error, sizeof(error)) != 0);
    assert(strstr(error, "variavel livre") != NULL);
    node_free(unknown);

    PifariF64Buffer buffer = {0};
    assert(pifari_f64_buffer_init(&buffer, 8) == 0);
    assert(buffer.length == 8 && buffer.data != NULL);
    assert(((uintptr_t)buffer.data % 64u) == 0);
    pifari_f64_buffer_destroy(&buffer);
    assert(buffer.data == NULL && buffer.length == 0);
    assert(pifari_f64_buffer_init(&buffer, SIZE_MAX) != 0);

    puts("AST -> IR / buffer F64: OK");
    return 0;
}

#include "../backend/dirac.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    PifariDiracExpr *ket = pifari_dirac_symbol(PIFARI_DIRAC_KET, "psi");
    PifariDiracExpr *bra = pifari_dirac_adjoint(ket);
    PifariDiracExpr *inner = pifari_dirac_compose(bra, ket);
    char *text = pifari_dirac_format(inner);
    assert(text && strcmp(text, "<psi|psi>") == 0);
    free(text);

    PifariDiracExpr *a = pifari_dirac_symbol(PIFARI_DIRAC_OPERATOR, "A");
    PifariDiracExpr *b = pifari_dirac_symbol(PIFARI_DIRAC_OPERATOR, "B");
    PifariDiracExpr *product = pifari_dirac_compose(a, b);
    PifariDiracExpr *adjoint = pifari_dirac_adjoint(product);
    text = pifari_dirac_format(adjoint);
    assert(text && strstr(text, "†") != NULL);
    free(text);

    pifari_dirac_free(ket);
    pifari_dirac_free(bra);
    pifari_dirac_free(inner);
    pifari_dirac_free(a);
    pifari_dirac_free(b);
    pifari_dirac_free(product);
    pifari_dirac_free(adjoint);
    puts("Dirac symbolic algebra: OK");
    return 0;
}

#include "../backend/optimization/native_kernel.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    PifariExprGraph graph;
    pifari_graph_init(&graph);
    int input = pifari_graph_add(&graph, PEX_INPUT, -1, -1, 0.0);
    int two = pifari_graph_add(&graph, PEX_CONST, -1, -1, 2.0);
    int mul = pifari_graph_add(&graph, PEX_MUL, input, two, 0.0);
    int one = pifari_graph_add(&graph, PEX_CONST, -1, -1, 1.0);
    graph.root = pifari_graph_add(&graph, PEX_ADD, mul, one, 0.0);

    PifariNativeKernel *kernel = NULL;
    assert(pifari_native_kernel_create(&graph, &kernel) == 0);
    double input_values[] = {1, 2, 3, 4};
    double output_values[4] = {0};
    assert(pifari_native_kernel_map(kernel, input_values, output_values, 4, 1) == 0);
    for (size_t i = 0; i < 4; ++i)
        assert(output_values[i] == input_values[i] * 2 + 1);
    size_t length = 20000;
    double *large_input = malloc(length * sizeof(*large_input));
    double *large_output = malloc(length * sizeof(*large_output));
    assert(large_input && large_output);
    for (size_t i = 0; i < length; ++i)
        large_input[i] = (double)i - 10000.0;
    assert(pifari_native_kernel_map(kernel, large_input, large_output, length, 4) == 0);
    for (size_t i = 0; i < length; ++i)
        assert(large_output[i] == large_input[i] * 2.0 + 1.0);
    free(large_input);
    free(large_output);
    pifari_native_kernel_destroy(kernel);
    pifari_graph_destroy(&graph);

    pifari_graph_init(&graph);
    input = pifari_graph_add(&graph, PEX_INPUT, -1, -1, 0.0);
    int zero = pifari_graph_add(&graph, PEX_CONST, -1, -1, 0.0);
    graph.root = pifari_graph_add(&graph, PEX_DIV, input, zero, 0.0);
    assert(pifari_native_kernel_create(&graph, &kernel) == 0);
    assert(pifari_native_kernel_map(kernel, input_values, output_values, 4, 1) == -2);
    pifari_native_kernel_destroy(kernel);
    pifari_graph_destroy(&graph);
    puts("native fused kernel serial/parallel/error: OK");
    return 0;
}

#include "../backend/optimization/optimizer.h"
#include "../backend/optimization/operator_engine.h"
#include "../backend/optimization/memory_plan.h"
#include "../backend/reversible.h"
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
int main(void) {
    PifariExprGraph g;
    pifari_graph_init(&g);
    int x = pifari_graph_add(&g, PEX_INPUT, -1, -1, 0),
        two = pifari_graph_add(&g, PEX_CONST, -1, -1, 2);
    int three = pifari_graph_add(&g, PEX_CONST, -1, -1, 3),
        five = pifari_graph_add(&g, PEX_ADD, two, three, 0);
    int mul = pifari_graph_add(&g, PEX_MUL, x, five, 0),
        ten = pifari_graph_add(&g, PEX_CONST, -1, -1, 10);
    int add = pifari_graph_add(&g, PEX_ADD, mul, ten, 0),
        relu = pifari_graph_add(&g, PEX_MAX0, add, -1, 0);
    g.root = relu;
    assert(pifari_graph_optimize(&g) == 0);
    assert(g.nodes[five].op == PEX_CONST && g.nodes[five].constant == 5);
    double in[] = {-10, -2, 0, 3}, out[4];
    assert(pifari_graph_map(&g, in, out, 4) == 0);
    assert(out[0] == 0 && out[1] == 0 && out[2] == 10 && out[3] == 25);
    size_t n = 20000;
    double *large_in = malloc(n * sizeof(double)), *large_seq = malloc(n * sizeof(double)),
           *large_par = malloc(n * sizeof(double));
    assert(large_in && large_seq && large_par);
    for (size_t i = 0; i < n; i++)
        large_in[i] = (double)((int)(i % 101) - 50);
    assert(pifari_graph_map(&g, large_in, large_seq, n) == 0);
    assert(pifari_graph_map_parallel(&g, large_in, large_par, n, 4) == 0);
    for (size_t i = 0; i < n; i++)
        assert(large_seq[i] == large_par[i]);
    free(large_in);
    free(large_seq);
    free(large_par);
    pifari_graph_destroy(&g);
    pifari_graph_init(&g);
    int dx = pifari_graph_add(&g, PEX_INPUT, -1, -1, 0),
        dz = pifari_graph_add(&g, PEX_CONST, -1, -1, 0);
    g.root = pifari_graph_add(&g, PEX_DIV, dx, dz, 0);
    double bad = 0;
    assert(pifari_graph_optimize(&g) == 0);
    assert(pifari_graph_eval(&g, 1, &bad) == -2);
    pifari_graph_destroy(&g);
    double a[] = {-2, 0, 3}, b[3];
    assert(pifari_kernel_affine_relu(a, b, 3, 2, -1, 4) == 0);
    assert(b[0] == 0 && b[1] == 0 && b[2] == 5);
    size_t big_n = 20000;
    double *big_in = malloc(big_n * sizeof(double)), *big_out = malloc(big_n * sizeof(double));
    assert(big_in && big_out);
    for (size_t i = 0; i < big_n; i++)
        big_in[i] = (double)(i % 101) - 50.0;
    assert(pifari_kernel_affine_relu(big_in, big_out, big_n, 2.0, 1.0, 4) == 0);
    for (size_t i = 0; i < big_n; i++) {
        double expected = 2.0 * big_in[i] + 1.0;
        if (expected < 0)
            expected = 0;
        assert(big_out[i] == expected);
    }
    free(big_in);
    free(big_out);
    PifariLiveRange lr[] = {{0, 2, 0}, {3, 4, 0}, {1, 3, 0}};
    assert(pifari_plan_slots(lr, 3) == 2);
    uint64_t bits[] = {0, 1, UINT64_C(0x123456789abcdef0)}, original[3];
    for (int i = 0; i < 3; i++)
        original[i] = bits[i];
    pifari_xor_transform(bits, 3, UINT64_C(0xa5a5a5a5a5a5a5a5));
    pifari_xor_transform(bits, 3, UINT64_C(0xa5a5a5a5a5a5a5a5));
    for (int i = 0; i < 3; i++)
        assert(bits[i] == original[i]);
    PifariReversibleProgram program;
    pifari_reversible_init(&program);
    assert(pifari_reversible_add_xor(&program, 0, UINT64_C(0x55)) == 0);
    assert(pifari_reversible_add_not(&program, 1) == 0);
    assert(pifari_reversible_add_swap(&program, 0, 2) == 0);
    uint64_t state[] = {11, 22, 33}, saved[] = {11, 22, 33};
    assert(pifari_reversible_apply(&program, state, 3) == 0);
    assert(state[0] != saved[0] || state[1] != saved[1] || state[2] != saved[2]);
    assert(pifari_reversible_uncompute(&program, state, 3) == 0);
    for (size_t i = 0; i < 3; i++)
        assert(state[i] == saved[i]);
    pifari_reversible_destroy(&program);
    puts("optimizer/operator-engine/memory-plan/reversible: OK");
    return 0;
}
